# ctypes & wintypes 임포트 (Windows 64-bit safe)
if sys.platform == "win32":
    import ctypes
    from ctypes import wintypes

    _kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

    _SYNCHRONIZE = 0x00100000
    _PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
    _WAIT_OBJECT_0 = 0x00000000
    _WAIT_TIMEOUT = 0x00000102
    _ERROR_INVALID_PARAMETER = 87

    _OpenProcess = _kernel32.OpenProcess
    _OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    _OpenProcess.restype = wintypes.HANDLE

    _WaitForSingleObject = _kernel32.WaitForSingleObject
    _WaitForSingleObject.argtypes = [wintypes.HANDLE, wintypes.DWORD]
    _WaitForSingleObject.restype = wintypes.DWORD

    _CloseHandle = _kernel32.CloseHandle
    _CloseHandle.argtypes = [wintypes.HANDLE]
    _CloseHandle.restype = wintypes.BOOL

def _alive_win32(pid: int) -> str:
    """Windows 전용 3상태 liveness 판정 ('ALIVE', 'DEAD', 'UNKNOWN')"""
    handle = _OpenProcess(_SYNCHRONIZE | _PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if not handle:
        err = ctypes.get_last_error()
        if err == _ERROR_INVALID_PARAMETER:
            return "DEAD"
        return "UNKNOWN"

    try:
        res = _WaitForSingleObject(handle, 0)
        if res == _WAIT_TIMEOUT:
            return "ALIVE"
        elif res == _WAIT_OBJECT_0:
            return "DEAD"
        else:
            return "UNKNOWN"
    finally:
        _CloseHandle(handle)

def _alive(pid: int) -> bool:
    if sys.platform == "win32":
        status = _alive_win32(pid)
        if status == "ALIVE":
            return True
        elif status == "DEAD":
            return False
        else: # UNKNOWN (ERROR_ACCESS_DENIED 등) -> fail-closed (safe)
            return True
    else:
        try:
            os.kill(pid, 0)
            return True
        except OSError:
            return False
